create table public.integration_connections(user_id uuid not null references auth.users(id) on delete cascade, kind text not null check(kind in ('gmail','google_calendar')),account_email text not null check(length(account_email) between 3 and 320),connected_at timestamptz not null default clock_timestamp(),primary key(user_id,kind));
create table public.integration_secrets(user_id uuid not null,kind text not null,ciphertext text not null check(length(ciphertext) between 20 and 32768),access_expires_at timestamptz not null,refresh_lease uuid,refresh_until timestamptz,primary key(user_id,kind),foreign key(user_id,kind) references public.integration_connections(user_id,kind) on delete cascade);
create table public.integration_oauth_pending(user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in ('gmail','google_calendar')),state_hash text not null unique check(state_hash ~ '^[a-f0-9]{64}$'),verifier_ciphertext text not null check(length(verifier_ciphertext) between 20 and 1024),expires_at timestamptz not null,claimed boolean not null default false,primary key(user_id,kind));
alter table public.integration_connections enable row level security;alter table public.integration_secrets enable row level security;alter table public.integration_oauth_pending enable row level security;
create policy integration_connections_owner on public.integration_connections for select to authenticated using(user_id=(select auth.uid()));grant select on public.integration_connections to authenticated;grant select on public.integration_secrets to service_role;
create function public.start_google_oauth(p_user uuid,p_kind text,p_hash text,p_verifier text) returns void language plpgsql security definer set search_path='' as $$ begin insert into public.integration_oauth_pending(user_id,kind,state_hash,verifier_ciphertext,expires_at,claimed) values(p_user,p_kind,p_hash,p_verifier,clock_timestamp()+interval '10 minutes',false) on conflict(user_id,kind) do update set state_hash=excluded.state_hash,verifier_ciphertext=excluded.verifier_ciphertext,expires_at=excluded.expires_at,claimed=false; end $$;
create function public.claim_google_oauth(p_user uuid,p_hash text) returns jsonb language plpgsql security definer set search_path='' as $$ declare pending public.integration_oauth_pending%rowtype;begin update public.integration_oauth_pending set claimed=true where user_id=p_user and state_hash=p_hash and not claimed and expires_at>clock_timestamp() returning * into pending;if not found then return null;end if;return jsonb_build_object('kind',pending.kind,'verifier',pending.verifier_ciphertext);end $$;
create function public.finish_google_oauth(p_user uuid,p_kind text,p_hash text,p_email text,p_ciphertext text,p_expires timestamptz) returns boolean language plpgsql security definer set search_path='' as $$ begin perform 1 from public.integration_oauth_pending where user_id=p_user and kind=p_kind and state_hash=p_hash and claimed and expires_at>clock_timestamp() for update;if not found then return false;end if;insert into public.integration_connections(user_id,kind,account_email,connected_at) values(p_user,p_kind,p_email,clock_timestamp()) on conflict(user_id,kind) do update set account_email=excluded.account_email,connected_at=excluded.connected_at;insert into public.integration_secrets(user_id,kind,ciphertext,access_expires_at,refresh_lease,refresh_until) values(p_user,p_kind,p_ciphertext,p_expires,null,null) on conflict(user_id,kind) do update set ciphertext=excluded.ciphertext,access_expires_at=excluded.access_expires_at,refresh_lease=null,refresh_until=null;delete from public.integration_oauth_pending where user_id=p_user and kind=p_kind and state_hash=p_hash;return true;end $$;
create function public.claim_google_refresh(p_user uuid,p_kind text,p_lease uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare secret public.integration_secrets%rowtype;begin if p_lease is null then return null;end if;update public.integration_secrets set refresh_lease=p_lease,refresh_until=clock_timestamp()+interval '45 seconds' where user_id=p_user and kind=p_kind and access_expires_at<=clock_timestamp()+interval '60 seconds' and (refresh_until is null or refresh_until<clock_timestamp()) returning * into secret;if not found then return null;end if;return jsonb_build_object('ciphertext',secret.ciphertext);end $$;
create function public.finish_google_refresh(p_user uuid,p_kind text,p_lease uuid,p_ciphertext text,p_expires timestamptz) returns boolean language plpgsql security definer set search_path='' as $$ begin update public.integration_secrets set ciphertext=p_ciphertext,access_expires_at=p_expires,refresh_lease=null,refresh_until=null where user_id=p_user and kind=p_kind and refresh_lease=p_lease and refresh_until>clock_timestamp();return found;end $$;
create function public.disconnect_google(p_user uuid,p_kind text) returns void language plpgsql security definer set search_path='' as $$ begin delete from public.integration_oauth_pending where user_id=p_user and kind=p_kind;delete from public.integration_connections where user_id=p_user and kind=p_kind;end $$;
revoke all on function public.start_google_oauth(uuid,text,text,text),public.claim_google_oauth(uuid,text),public.finish_google_oauth(uuid,text,text,text,text,timestamptz),public.claim_google_refresh(uuid,text,uuid),public.finish_google_refresh(uuid,text,uuid,text,timestamptz),public.disconnect_google(uuid,text) from public;
grant execute on function public.start_google_oauth(uuid,text,text,text),public.claim_google_oauth(uuid,text),public.finish_google_oauth(uuid,text,text,text,text,timestamptz),public.claim_google_refresh(uuid,text,uuid),public.finish_google_refresh(uuid,text,uuid,text,timestamptz),public.disconnect_google(uuid,text) to service_role;
